1	package org.springframework.samples.petclinic.rest.escalation;
2	
3	import java.util.List;
4	
5	/**
6	 * Thrown when a create-owner request omits or blanks a required field.
7	 * Handled by {@link MissingOwnerFieldsExceptionHandler}, which responds 400 with an
8	 * {@code errors} array naming each missing field.
9	 */
10	public class MissingOwnerFieldsException extends Exception {
11	
12	    private final List<String> fields;
13	
14	    public MissingOwnerFieldsException(List<String> fields) {
15	        super("Owner is missing required fields: " + String.join(", ", fields));
16	        this.fields = List.copyOf(fields);
17	    }
18	
19	    /** The names of the required fields that were missing or blank. */
20	    public List<String> getFields() {
21	        return fields;
22	    }
23	}
